package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io/ioutil"
	"net/http"
)

type Content struct {
	Parts []struct {
		Text string `json:"text"`
	} `json:"parts"`
}

type EmbedContentRequest struct {
	Model string `json:"model"`
	Content Content `json:"content"`
}

func main() {
	var request EmbedContentRequest
	request.Model = "models/gemini-embedding-001"
	request.Content.Parts = []struct {
		Text string `json:"text"`
	}{
		{
			Text: "What is the meaning of life?",
		},
		{
			Text: "How much wood would a woodchuck chuck?",
		},
		{
			Text: "How does the brain work?",
		},
	}

	jsonBytes, err := json.Marshal(request)
	if err != nil {
		fmt.Println(err)
		return
	}

	req, err := http.NewRequest("POST", "https://generativelanguage.googleapis.com/v1beta/models/gemini-embedding-001:embedContent", bytes.NewBuffer(jsonBytes))
	if err != nil {
		fmt.Println(err)
		return
	}

	req.Header.Set("x-goog-api-key", "YOUR_API_KEY")

	client := &http.Client{}
	resp, err := client.Do(req)
	if err != nil {
		fmt.Println(err)
		return
	}
	defer resp.Body.Close()

	body, err := ioutil.ReadAll(resp.Body)
	if err != nil {
		fmt.Println(err)
		return
	}

	fmt.Println(string(body))
}

